// seed: tests/seed.user.spec.ts · ПРОД, только шаг 1, «שלב הבא» не нажимается, запись обрывается.
import { test, expect } from '@playwright/test';
import {
  ABROAD_CATEGORY, ABROAD_TEXT, ABROAD_TYPE, HALLS_CATEGORY, SALE_TYPE,
  abroadField, expectAbroadMode, expectCityMode, expectNoWrites, openWizard, pick, prepare,
} from './overseas.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });

test.describe('addbusiness — место бизнеса за границей (шаг 1)', () => {
  test('«עסקים בחו"ל» — свободное поле «מיקום העסק בחו"ל*» вместо города/адреса/района #75ae6c @desktop @prod-safe', async ({ page, context }) => {
    const ctl = await prepare(context);
    await openWizard(page);
    await expectCityMode(page); // до выбора типа — обычный выбор города
    await pick(page, 'קטגוריה', HALLS_CATEGORY);
    await pick(page, 'סוג מודעה', ABROAD_TYPE);
    await expectAbroadMode(page);
    expectNoWrites(ctl);
  });

  test('смена типа на «עסקים למסירה - מכירה» и обратно — поле городов вернулось, затем текст места сохранён #75ae6c @desktop @prod-safe', async ({ page, context }) => {
    const ctl = await prepare(context);
    await openWizard(page);
    await pick(page, 'קטגוריה', HALLS_CATEGORY);
    await pick(page, 'סוג מודעה', ABROAD_TYPE);
    await abroadField(page).fill(ABROAD_TEXT);

    await pick(page, ABROAD_TYPE, SALE_TYPE);
    await expectCityMode(page);

    await pick(page, SALE_TYPE, ABROAD_TYPE);
    await expectAbroadMode(page);
    await expect(abroadField(page), 'введённый текст места сохранился').toHaveValue(ABROAD_TEXT);
    expectNoWrites(ctl);
  });

  test('категория «חו"ל» — свободное поле места (регресс #9899c0) #75ae6c @desktop @prod-safe', async ({ page, context }) => {
    const ctl = await prepare(context);
    await openWizard(page);
    await pick(page, 'קטגוריה', ABROAD_CATEGORY);
    await expectAbroadMode(page);
    expectNoWrites(ctl);
  });
});
